labels = {'carton': 'كرتون', 'bag': 'جرم', 'foam': 'فلين'}
for r in records:
    t = r.x_type
    if not t:
        continue
    if t == 'loose':
        new_name = 'فرط (بالكيلو)'
    elif t == 'piece':
        new_name = 'حبة (بالحبة)'
    else:
        label = labels.get(t, '')
        w = r.x_approx_weight_kg or 0
        if w and w > 0:
            wf = float(w)
            if wf == int(wf):
                w_txt = str(int(wf))
            else:
                w_txt = ('%f' % wf).rstrip('0').rstrip('.')
            new_name = label + ' · ' + w_txt + ' كيلو'
        else:
            new_name = label
    if r.x_name != new_name:
        r.write({'x_name': new_name})

